WITH filtered_customers AS (SELECT *, COALESCE(email, 'N/A') email_filled FROM customers WHERE credit_limit BETWEEN 6100 AND 10700 AND is_active), customers_stats AS (SELECT country, ROUND(STDDEV(age), 2) stddev_age, MAX(signup_date) latest_signup_date FROM filtered_customers GROUP BY country) SELECT country, latest_signup_date FROM customers_stats WHERE stddev_age < 61 ORDER BY country DESC, latest_signup_date LIMIT 10;
